  "summary": "A long-running container service behind the load balancer.",
  "schema": {
    "$defs": {
      "Probe": {
        "additionalProperties": false,
        "properties": {
          "path": {
            "default": "/healthz",
            "title": "Path",
            "type": "string"
          },
          "interval_seconds": {
            "default": 5,
            "minimum": 1,
            "title": "Interval Seconds",
            "type": "integer"
          },
          "timeout_seconds": {
            "default": 2,
            "minimum": 1,
            "title": "Timeout Seconds",
            "type": "integer"
          },
          "failure_threshold": {
            "default": 3,
            "minimum": 1,
            "title": "Failure Threshold",
            "type": "integer"
          }
        },
        "title": "Probe",
        "type": "object"
      }
    },
    "additionalProperties": false,
    "properties": {
      "source": {
        "default": "upload",
        "description": "Where releases come from; 'upload' means `sc deploy` archives.",
        "title": "Source",
        "type": "string"
      },
      "build": {
        "description": "Run once per release in the source root, e.g. ['pip', 'install', '-r', 'requirements.txt', '-t', 'deps'].",
        "items": {
          "type": "string"
        },
        "title": "Build",
        "type": "array"
      },
      "command": {
        "description": "Start command for each instance; it must listen on $PORT.",
        "items": {
          "type": "string"
        },
        "title": "Command",
        "type": "array"
      },
      "port": {
        "default": 8080,
        "maximum": 65535,
        "minimum": 1,
        "title": "Port",
        "type": "integer"
      },
      "env": {
        "additionalProperties": {
          "type": "string"
        },
        "title": "Env",
        "type": "object"
      },
      "secrets": {
        "additionalProperties": {
          "type": "string"
        },
        "description": "Env var -> secret name; mounted at start, never logged.",
        "title": "Secrets",
        "type": "object"
      },
      "databases": {
        "additionalProperties": {
          "type": "string"
        },
        "description": "Env var -> database name; a DSN with short-lived credentials, issued at start as the service account (needs database:connect).",
        "title": "Databases",
        "type": "object"
      },
      "min_instances": {
        "default": 1,
        "minimum": 0,
        "title": "Min Instances",
        "type": "integer"
      },
      "max_instances": {
        "default": 3,
        "minimum": 1,
        "title": "Max Instances",
        "type": "integer"
      },
      "cpu_millis": {
        "default": 500,
        "minimum": 100,
        "title": "Cpu Millis",
        "type": "integer"
      },
      "memory_mb": {
        "default": 512,
        "minimum": 64,
        "title": "Memory Mb",
        "type": "integer"
      },
      "readiness": {
        "$ref": "#/$defs/Probe"
      },
      "service_account": {
        "anyOf": [
          {
            "type": "string"
          },
          {
            "type": "null"
          }
        ],
        "default": null,
        "title": "Service Account"
      },
      "regions": {
        "items": {
          "type": "string"
        },
        "title": "Regions",
        "type": "array"
      },
      "drain_seconds": {
        "default": 10,
        "description": "Time a stopping instance keeps serving in-flight requests.",
        "minimum": 0,
        "title": "Drain Seconds",
        "type": "integer"
      },
      "rollout_timeout_seconds": {
        "default": 120,
        "description": "A release that isn't ready within this time fails and is not routed to.",
        "maximum": 1800,
        "minimum": 5,
        "title": "Rollout Timeout Seconds",
        "type": "integer"
      }
    },
    "title": "ServiceSpec",
    "type": "object"
  }
}

